// Politique de démonstration : les plafonds métier ne peuvent pas être élargis depuis la matrice.
// r = lecture, w = modification, v = validation, c = paramétrage.
const featureSpec={
 dashboard:{label:'Tableaux de bord et exports',cap:{admin:'r',coordinator:'r',tutor:'r',student:'r',company:'r',promotion:'r'}},
 profile:{label:'Profil et mot de passe personnels',cap:{admin:'rw',coordinator:'rw',tutor:'rw',student:'rw',company:'rw',promotion:'rw'}},
 notifications:{label:'Notifications personnelles',cap:{admin:'rw',coordinator:'rw',tutor:'rw',student:'rw',company:'rw',promotion:'rw'}},
 accounts:{label:'Comptes, rôles et état des comptes',cap:{admin:'rc'}},
 matrix:{label:'Matrice des droits',cap:{admin:'rc'}},
 settings:{label:'Paramètres et capacités',cap:{admin:'rc',coordinator:'rc'},defaults:{coordinator:''}},
 logs:{label:'Journaux et historique des imports',cap:{admin:'r'}},
 dossier:{label:'Dossiers étudiants — vue générale',cap:{coordinator:'r',tutor:'r',student:'r',company:'r'}},
 accesses:{label:'Déclaration et accès maître de stage',cap:{coordinator:'rwv',student:'rw'}},
 cra:{label:'Synthèses CRA, demandes et réponses',cap:{coordinator:'r',tutor:'rw',student:'rw'}},
 visits:{label:'Visites : demandes, proposition et confirmation',cap:{coordinator:'r',tutor:'rv',student:'rw',company:'r'}},
 crv:{label:'Bilans CRV, désaccords et visas',cap:{coordinator:'rv',tutor:'rwv',student:'rwv',company:'rwv'}},
 missions:{label:'Missions : proposition et réponse',cap:{coordinator:'rw',tutor:'rv'}},
 availability:{label:'Disponibilité du tuteur',cap:{tutor:'rw'}},
 reports:{label:'Signalements et clôture',cap:{coordinator:'rwv',tutor:'rw',student:'rw',company:'rw'}},
 imports:{label:'Import Excel / CSV et création des dossiers',cap:{coordinator:'rwv'}},
 transition:{label:'Bascule M1 → M2 et sortie',cap:{coordinator:'rv'}},
 projectchat:{label:'Canaux et messages de dossier',cap:{coordinator:'rw',tutor:'rw',student:'rw',company:'rw'}},
 channels:{label:'Ouverture et fermeture des canaux',cap:{coordinator:'rc'}},
 mail:{label:'Messagerie par adresse entre comptes',cap:{admin:'rw',coordinator:'rw',tutor:'rw',student:'rw',company:'rw',promotion:'rw'}}
};
const actionNames={read:'Lecture',write:'Modification',validate:'Validation',configure:'Paramétrage'};
const actionCode={read:'r',write:'w',validate:'v',configure:'c'};
const maxPages={dashboard:'dashboard',cohort:'dashboard',profile:'profile',students:'dossier',dossier:'dossier',missions:'missions',availability:'availability',requests:'accesses',reports:'reports',rooms:'projectchat',assign:'missions',transition:'transition',mailbox:'mail',import:'imports',settings:'settings',channeladmin:'channels',audit:'logs',logs:'logs',importhistory:'logs',accounts:'accounts',permissions:'matrix'};
const tabFeatures={overview:'dossier',cra:'cra',visits:'visits',crv:'crv',messages:'projectchat'};
let matrixRole='coordinator';
function initMax(){
 data.rights ||= {};
 for(const r of Object.keys(roles)){
  data.rights[r] ||= {};
  for(const [feature,spec] of Object.entries(featureSpec)){
   const cap=spec.cap[r]||'';
   if(!Array.isArray(data.rights[r][feature])){
    let initial=spec.defaults?.[r]??cap;
    const old=data.permissions?.[r]?.[feature];
    if(r!=='admin'&&typeof old==='string'){if(old==='none')initial='';else if(old==='read')initial=cap.includes('r')?'r':'';else if(old==='write')initial=cap}
    data.rights[r][feature]=Object.entries(actionCode).filter(([,code])=>initial.includes(code)).map(([name])=>name);
   }
   data.rights[r][feature]=data.rights[r][feature].filter(a=>cap.includes(actionCode[a]||'!'));
  }
 }
 data.directMessages ||= [];data.connectionLogs ||= [];data.importHistory ||= [];data.closedChannels ||= {};
}
function permission(feature,action='read'){
 const cap=featureSpec[feature]?.cap[role]||'',code=actionCode[action];
 if(!code||!cap.includes(code))return false;
 if(role==='admin')return true; // Only the explicitly listed administrative/personal capabilities above.
 const grants=data.rights[role]?.[feature]||[];
 return grants.includes('read')&&(action==='read'||grants.includes(action));
}
function maxNav(){
 if(role==='admin')return [['dashboard','Tableau de bord','dashboard'],['accounts','Comptes et rôles','users'],['permissions','Matrice des droits','shield'],['settings','Paramétrage','settings'],['audit','Journal d’activité','file'],['logs','Journal des connexions','shield'],['importhistory','Historique des imports','file'],['mailbox','Ma messagerie','message']].filter(([p])=>permission(maxPages[p]));
 const items=[...nav[role]];const add=(p,l,i)=>{if(!items.some(x=>x[0]===p))items.push([p,l,i])};
 if(permission('mail'))add('mailbox','Messagerie par e-mail','message');if(permission('settings'))add('settings','Paramètres de suivi','settings');if(permission('channels'))add('channeladmin','Gestion des canaux','users');
 return items.filter(([p])=>!maxPages[p]||permission(maxPages[p]));
}
function formOperation(form){const f=form.id;const map={'profile-form':['profile','write'],'password-form':['profile','write'],'new-account-form':['accounts','configure'],'settings-form':['settings','configure'],'edit-student-form':['accesses','write'],'supervisor-form':['accesses','write'],'cra-form':['cra','write'],'cra-request-form':['cra','write'],'visits-request-form':['visits','validate'],'visit-form':['visits','write'],'amend-form':['crv','write'],'note-form':['reports','write'],'report-form':['reports','write'],'mission-form':['missions','write'],'import-form':['imports','validate'],'message-form':['projectchat','write'],'room-form':['projectchat','write'],'floating-message-form':['projectchat','write'],'direct-form':['mail','write']};return form.classList.contains('feedback-form')?['cra','write']:map[f]||null}
function buttonOperation(b){const d=b.dataset;if(d.read||d.action==='read-all')return ['notifications','write'];if(d.missionAccept||d.missionReject)return ['missions','validate'];if(d.missionCancel)return ['missions','write'];if(d.availability)return ['availability','write'];if(d.channelToggle)return ['channels','configure'];if(d.confirm||d.alternative||d.visited)return ['visits','validate'];if(d.createAccess)return ['accesses','validate'];if(d.editStudent)return ['accesses','write'];if(d.reportAction)return ['reports',d.reportAction.startsWith('close|')||d.reportAction.startsWith('rupture|')?'validate':'write'];if(d.transition)return ['transition','validate'];if(d.archiveAccount||d.action==='new-account')return ['accounts','configure'];if(d.restoreStudent)return ['transition','validate'];if(d.command||d.action==='insert-table'||d.action==='save-crv'||d.action==='dispute')return ['crv','write'];if(d.action==='visa'||d.action==='arbitrate')return ['crv','validate'];return null}
function applyReadOnly(){
 app.querySelectorAll('form').forEach(form=>{if(form.id==='import-form'){if(!permission('imports','write'))form.querySelectorAll('input,textarea').forEach(el=>el.disabled=true);if(!permission('imports','write')||!permission('imports','validate'))form.querySelectorAll('button[type=submit],button:not([type])').forEach(el=>el.disabled=true);return}const op=formOperation(form);if(op&&!permission(...op)){form.querySelectorAll('input,textarea,select,button').forEach(el=>el.disabled=true);const note=document.createElement('p');note.className='subtle';note.textContent=`Action non autorisée (${actionNames[op[1]].toLowerCase()}).`;form.prepend(note)}});
 const editor=document.getElementById('crv-editor');if(editor&&!permission('crv','write'))editor.contentEditable='false';app.querySelectorAll('button').forEach(b=>{const op=buttonOperation(b);if(op&&!permission(...op)){b.disabled=true;b.title=`${actionNames[op[1]]} non autorisée`}});
}
function accessLog(email,event,detail=''){data.connectionLogs.unshift({date:dateTime(),email:email||'Adresse inconnue',event,detail});data.connectionLogs=data.connectionLogs.slice(0,1000)}
function importLog(name,created,updated,rejected,detail){data.importHistory.unshift({date:dateTime(),actor:session,role,file:name||'Saisie manuelle',created,updated,rejected,detail});data.importHistory=data.importHistory.slice(0,500)}
function permissionsPage(){
 const names=Object.keys(roles);const chosen=roles[matrixRole]?matrixRole:'coordinator';
 return `${heading('ADMINISTRATION','Matrice des droits','Lecture, modification, validation et paramétrage : les plafonds métier restent prioritaires.')}
 <div class="notice">L’administrateur gère les accès et paramètres, mais n’accède pas aux dossiers et ne valide pas les opérations métier. Les cases indisponibles correspondent aux actions hors du périmètre du rôle. La lecture est requise pour toute autre action. Simulation locale.</div>
 <div class="card pad"><div class="field" style="max-width:360px"><label for="matrix-role">Rôle à examiner</label><select id="matrix-role">${names.map(r=>`<option value="${r}" ${r===chosen?'selected':''}>${esc(roles[r])}</option>`).join('')}</select></div>
 <div class="table-wrap"><table class="rights-matrix"><thead><tr><th>Fonctionnalité</th>${Object.values(actionNames).map(n=>`<th>${n}</th>`).join('')}</tr></thead><tbody>${Object.entries(featureSpec).map(([feature,spec])=>`<tr><td><strong>${esc(spec.label)}</strong></td>${Object.entries(actionCode).map(([action,code])=>{const allowed=(spec.cap[chosen]||'').includes(code),has=chosen==='admin'?allowed:(data.rights[chosen]?.[feature]||[]).includes(action);return `<td data-action-label="${esc(actionNames[action])}">${allowed?`<input type="checkbox" data-right="${chosen}|${feature}|${action}" aria-label="${esc(`${roles[chosen]} · ${spec.label} · ${actionNames[action]}`)}" ${has?'checked':''} ${chosen==='admin'||(action!=='read'&&!data.rights[chosen][feature].includes('read'))?'disabled':''}>`:'<span class="subtle">—</span>'}</td>`}).join('')}</tr>`).join('')}</tbody></table></div></div>`;
}
function mailboxPage(){const allowed=role==='admin'?data.directMessages:data.directMessages.filter(m=>m.from===session||m.to===session);return `${heading('COMMUNICATION','Messagerie par e-mail','Échangez avec les comptes actifs de la plateforme, quel que soit leur rôle.')}<div class="notice">Les adresses identifient les comptes de cette démonstration : aucun e-mail réel n’est envoyé. Les messages sont visibles par l’expéditeur, le destinataire et l’administrateur à des fins de consultation.</div><div class="max-mail-layout"><div class="card pad"><div class="max-title"><div><h2 class="section-title">${role==='admin'?'Consultation des messages entre comptes':'Vos échanges'}</h2><p class="section-desc">${allowed.length} message(s) · ${role==='admin'?'lecture administrative, envoi uniquement en votre nom':esc(session)}</p></div><span class="action-icon">${icon('message',18)}</span></div><div class="max-mail-list">${allowed.length?allowed.slice().reverse().map(m=>`<article class="max-mail"><div class="max-mail-head"><strong>${esc(person(m.from))}</strong><small>${esc(m.date)}</small></div><div class="subtle">De ${esc(m.from)} à ${esc(m.to)}</div>${m.body?`<p>${esc(m.body)}</p>`:''}${filesView(m.files)}</article>`).join(''):'<div class="empty">Aucun échange pour le moment.</div>'}</div></div><div class="card pad"><h2 class="section-title">Nouveau message</h2><p class="section-desc">Choisissez un compte actif par son adresse.</p>${permission('mail','write')?`<form id="direct-form" class="form"><div class="field"><label for="direct-to">Destinataire</label><select id="direct-to" required><option value="">Choisir une personne</option>${data.accounts.filter(a=>!a.archived&&a.email!==session).sort((a,b)=>a.name.localeCompare(b.name)).map(a=>`<option value="${esc(a.email)}">${esc(a.name)} · ${esc(a.email)}</option>`).join('')}</select></div><div class="field"><label for="direct-body">Message</label><textarea id="direct-body" placeholder="Écrivez votre message…"></textarea></div><div class="field"><label for="direct-file">${icon('paperclip',15)} Pièce jointe facultative · 1 Mo max.</label><input class="input" type="file" id="direct-file"></div><button class="btn primary">Envoyer le message</button></form>`:'<div class="notice">Votre rôle dispose d’un accès en lecture seule.</div>'}</div></div>`}
function channelAdminPage(){return `${heading('ADMINISTRATION','Gestion des canaux','Suivez les participants et ouvrez ou fermez les échanges des dossiers.')}<div class="notice">Les participants sont calculés à partir des affectations. Fermer un canal empêche les nouveaux messages du dossier mais conserve l’historique.</div><div class="card pad">${visibleStudents().map(s=>{const closed=!!data.closedChannels[s.id];return `<div class="max-channel"><div><strong>${esc(s.name)}</strong><p>${esc(s.company||'Entreprise non renseignée')} · ${roomReady(s)?closed?'Fermé par administration':'Ouvert':'En attente des affectations'}</p><small>Participants : ${esc(parties(s).map(p=>person(p.email)+' ('+roles[p.role]+')').join(', '))}</small></div>${permission('channels','configure')?`<button class="btn sm ${closed?'primary':'danger'}" data-channel-toggle="${esc(s.id)}">${closed?'Rouvrir':'Fermer'}</button>`:''}</div>`}).join('')}</div>`}
